function AttachedTrack({track,video,muted}:{track:Track|undefined;video:boolean;muted:boolean}){
 const videoRef=useRef<HTMLVideoElement>(null);const audioRef=useRef<HTMLAudioElement>(null);
 useEffect(()=>{if(!track)return;const node=video?videoRef.current:audioRef.current;if(!node)return;track.attach(node);return()=>{track.detach(node);};},[track,video]);
 return video?<video ref={videoRef} autoPlay playsInline muted={muted} className="live-track-video"/>:<audio ref={audioRef} autoPlay muted={muted} className="live-track-audio"/>;
}
function participantRole(person:Participant){try{return String(JSON.parse(person.metadata||"{}").role||"")}catch{return ""}}

