 const teacher=role==="teacher";
 const [room,setRoom]=useState<Room|null>(null);const [people,setPeople]=useState<Participant[]>([]);const [phase,setPhase]=useState("در حال اتصال به کلاس…");const [error,setError]=useState("");const [mic,setMic]=useState(false);const [camera,setCamera]=useState(false);const [sharing,setSharing]=useState(false);const [screenShareAllowed,setScreenShareAllowed]=useState(role==="teacher");const [handRaised,setHandRaised]=useState(false);const [raisedHands,setRaisedHands]=useState<Record<string,boolean>>({});const [deviceRequest,setDeviceRequest]=useState<"mic"|"camera"|"all"|null>(null);const [tab,setTab]=useState<"chat"|"people">("chat");const [sidePanelOpen,setSidePanelOpen]=useState(false);const [messages,setMessages]=useState<ChatLine[]>([]);const [files,setFiles]=useState<SharedFile[]>([]);const[boardMedia,setBoardMedia]=useState<BoardMedia|null>(null);const[boardToolsOpen,setBoardToolsOpen]=useState(false);const [message,setMessage]=useState("");const [color,setColor]=useState("#2563eb");const [drawing,setDrawing]=useState(false);const [annotationLayer,setAnnotationLayer]=useState<"teacher"|"shared">("teacher");const[boardWidth,setBoardWidth]=useState(4);const[boardTool,setBoardTool]=useState<"pen"|"eraser"|"highlighter"|"line"|"rectangle"|"ellipse"|"text">("pen");const[boardFill,setBoardFill]=useState(false);const[boardText,setBoardText]=useState("متن روی تخته");const[boardEnabled,setBoardEnabled]=useState(true);const[boardVisible,setBoardVisible]=useState(true);const[boardFullscreen,setBoardFullscreen]=useState(false);const[canDraw,setCanDraw]=useState(role!=="student");const[chatMode,setChatMode]=useState<"public"|"private"|"closed">("public");const[privateTarget,setPrivateTarget]=useState("");const[privateFilter,setPrivateFilter]=useState<string[]|null>(null);const[menuFor,setMenuFor]=useState("");const[banned,setBanned]=useState<Array<{registrationId:number;fullName:string}>>([]);const[showBanned,setShowBanned]=useState(false);const[personPrefs,setPersonPrefs]=useState<Record<string,{visible:boolean;scale:number}>>({});const[showHidden,setShowHidden]=useState(false);
 const chatRef=useRef<HTMLDivElement>(null);const canvasRef=useRef<HTMLCanvasElement>(null);const studentCanvasRef=useRef<HTMLCanvasElement>(null);const sharedCanvasRef=useRef<HTMLCanvasElement>(null);const pdfCanvasRef=useRef<HTMLCanvasElement>(null);const peopleRef=useRef<Participant[]>([]);const lastPoint=useRef<{x:number;y:number}|null>(null);const boardAnchor=useRef<{x:number;y:number}|null>(null);const strokeBuffer=useRef<Record<string,any>|null>(null);const receivedFiles=useRef<string[]>([]);const serverState=useRef<any>(null);const lastAnnotationSignature=useRef("");const lastAnnotationId=useRef(0);const [pageCount,setPageCount]=useState(1);const [zoom,setZoom]=useState(1);const [classroomPage,setClassroomPage]=useState(1);const [classroomDocument,setClassroomDocument]=useState("");const [presentationMode,setPresentationMode]=useState<"board"|"pdf"|"camera"|"screen">("board");const [documentName,setDocumentName]=useState("");const [persistence,setPersistence]=useState<"permanent"|"session">("permanent");const [cleanupDays,setCleanupDays]=useState(1);const [boardScale,setBoardScale]=useState(1);const [videoPreset,setVideoPreset]=useState<"small"|"medium"|"large"|"gallery"|"teacher">("medium");const [videoMinimized,setVideoMinimized]=useState(false);const [videoVisible,setVideoVisible]=useState(true);const [pipSupported,setPipSupported]=useState(false);const annotationQueue=useRef<Record<string,unknown>[]>([]);const [videoPinned,setVideoPinned]=useState(false);const [videoPosition,setVideoPosition]=useState({x:.03,y:.03});const videoStageRef=useRef<HTMLDivElement>(null);const dragOffset=useRef<{x:number;y:number}|null>(null);
