    const sync=()=>refreshPeople(client!);client.on(RoomEvent.ParticipantConnected,sync);client.on(RoomEvent.ParticipantDisconnected,sync);client.on(RoomEvent.TrackSubscribed,(track,publication,participant)=>{if(track.kind===Track.Kind.Video){const remote=publication as RemoteTrackPublication;remote.setVideoQuality(VideoQuality.HIGH);if(participantRole(participant)==="teacher")remote.setVideoDimensions({width:1920,height:1080});}sync();});client.on(RoomEvent.TrackUnsubscribed,sync);client.on(RoomEvent.TrackPublished,sync);client.on(RoomEvent.TrackUnpublished,sync);client.on(RoomEvent.TrackMuted,sync);client.on(RoomEvent.TrackUnmuted,sync);client.on(RoomEvent.ActiveSpeakersChanged,sync);
    client.on(RoomEvent.ConnectionStateChanged,state=>setPhase(state==="connected"?"متصل به کلاس":state==="reconnecting"?"در حال اتصال مجدد…":"اتصال قطع شد"));
