    client.registerByteStreamHandler("classroom-file",async(reader,participant)=>{try{const chunks=await reader.readAll();const mime=reader.info.mimeType||"application/octet-stream";const blob=new Blob(chunks as BlobPart[],{type:mime});const url=URL.createObjectURL(blob);receivedFiles.current.push(url);const name=reader.info.name||"فایل کلاس";setFiles(old=>[...old,{id:reader.info.id,name,url,size:blob.size}]);setMessages(old=>[...old,{id:crypto.randomUUID(),name:participant.identity,text:`فایل فرستاد: ${name}`,at:Date.now(),own:false}]);}catch{setError("دریافت فایل کامل نشد.");}});
