 useEffect(()=>{let live=true;let busy=false;const sync=async()=>{if(busy)return;busy=true;try{const oldState=serverState.current;const afterId=oldState?lastAnnotationId.current:0;const knownDocumentId=encodeURIComponent(oldState?.documentId||"");const knownPage=oldState?.page||0;const response=await fetch(`/api/online-classes/${classId}/classroom?afterId=${afterId}&documentId=${knownDocumentId}&page=${knownPage}`,{cache:"no-store"});if(!response.ok)return;const state=await response.json();if(!live||Number(state.version)<Number(serverState.current?.version||0))return;const presentationChanged=state.presentationMode!==oldState?.presentationMode;if(presentationChanged&&(state.presentationMode==="board"||state.presentationMode==="pdf")){lastAnnotationId.current=0;lastAnnotationSignature.current="";}const pageChanged=!oldState||state.documentId!==oldState.documentId||state.page!==oldState.page;const changed=state.documentId!==oldState?.documentId||state.page!==oldState?.page||state.version!==oldState?.version;serverState.current=state;setClassroomPage(state.page||1);setZoom(Math.max(.5,Math.min(3,state.zoom||1)));setClassroomDocument(state.documentId||"");setPresentationMode(["board","pdf","camera","screen"].includes(state.presentationMode)?state.presentationMode:"board");setDocumentName(state.documentName||"");setPageCount(Math.max(1,state.pageCount||1));setPersistence(state.persistenceMode||"permanent");setCleanupDays(state.cleanupDays||1);setAnnotationLayer(state.annotationLayer==="shared"?"shared":"teacher");setBoardScale(Math.max(.5,Math.min(2,Number(state.boardScale)||1)));setBoardFullscreen(!!state.boardFullscreen);setBoardVisible(state.boardVisible!==false);if(!dragOffset.current)setVideoPosition({x:Math.max(0,Math.min(.95,Number(state.videoX)||0)),y:Math.max(0,Math.min(.95,Number(state.videoY)||0))});setVideoPinned(!!state.videoPinned);setVideoMinimized(!!state.videoMinimized);setVideoVisible(state.videoVisible!==false);if(["small","medium","large","gallery","teacher"].includes(state.videoPreset))setVideoPreset(state.videoPreset);setBoardEnabled(state.boardEnabled);setCanDraw(state.canDraw);if(changed){setBoardMedia(state.documentId?{url:`/api/online-classroom-documents/${state.documentId}`,kind:state.mimeType==="application/pdf"?"pdf":"image",name:state.documentName}:null);lastAnnotationSignature.current="";}const signature=(state.annotations||[]).map((a:any)=>a.id).join(",");if(pageChanged){lastAnnotationId.current=0;clearCanvas();}if(signature!==lastAnnotationSignature.current||pageChanged){lastAnnotationSignature.current=signature;for(const annotation of state.annotations||[]){try{drawBoardEvent(JSON.parse(annotation.eventJson));lastAnnotationId.current=Math.max(lastAnnotationId.current,Number(annotation.id)||0);}catch{}}}}catch{}finally{busy=false;}};void sync();const timer=setInterval(()=>void sync(),1200);return()=>{live=false;clearInterval(timer)};},[classId,role]);
 
